-- FUNCTION: cjams.personsearch_global_nosort(json)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       

DROP FUNCTION IF EXISTS cjams.personsearch_global_nosort_opt(json);

CREATE OR REPLACE FUNCTION cjams.personsearch_global_nosort_opt(searchobj json)
RETURNS TABLE(totalcount bigint, exactmatch boolean, rankno integer, source character varying, personid uuid,firstname character varying, middlename character varying, lastname character varying, 
dob timestamp without time zone, dangerlevel integer, dateofdeath timestamp without time zone, isapproxdod integer, suffix character varying, prefx character varying, deceased bit, socialmediasource character varying, 
userphoto text, ssn character varying, mdm_id character varying, dcn character varying, dl character varying, primaryaddress character varying, address character varying, address2 character varying, county character varying, 
city character varying, state character varying, zipcode character varying, homephone character varying, gendertypekey character varying, alias text, assistpid character varying, cjamspid character varying,
safehavenbabyflag integer, ethnicgrouptypekey character varying, cisclientid character varying, isbioadoptedflag integer)
LANGUAGE plpgsql
AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 ------------------------------------------------------------------------------------------------------------
-- Revision(s)
-- 09/14/2023 Palani/Chandra - Performance tugning (CIDM-7932)
--12/08/2023 Manasa Kasula - Performance tuning and search rifinement changes(CIDM-8201)

------------------------------------------------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
DECLARE
v_liPageNumber    INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
v_liPageSize      INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
v_lvFirstName     VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
v_lvLastName      VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
v_lvMiddleName    VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
v_liAge           INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
v_lvRace          VARCHAR(15);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
v_lvGender        VARCHAR(15);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
v_lvCity          VARCHAR(32);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
v_lvAddress       VARCHAR(100); 
v_lvAddress2      VARCHAR(100);
v_lvZip           VARCHAR(32);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
v_lvState         VARCHAR(32);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
v_lvCounty        VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
v_lvPhone         VARCHAR(32);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
v_ldDOB           varchar(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
v_lvRoleType      VARCHAR(10);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
v_liCount         INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
v_liDangerous     INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
v_liRegion        INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
v_lSSNValue  VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
v_lDCNValue  VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
v_lDLValue  VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
v_lvMaidenName  VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
v_lvSocialMediaSrc  VARCHAR(250);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
v_lvStateId  VARCHAR(150);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
v_lvOccupation  VARCHAR(150);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
v_lvFein  VARCHAR(50);
v_lvComplaintnumber  VARCHAR(50);
v_lvCjisnumber_spaced VARCHAR(50);
v_lvCjisnumber  VARCHAR(50);
v_lvcjamspid  VARCHAR(50);
v_lvPetitionid  VARCHAR(50);
v_lvAlias  VARCHAR(50);
v_lvEmail  VARCHAR(50);
v_pageoffset  int;
v_pagenumber  int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
v_lmdmValue  VARCHAR(50); 
v_firstname_clean varchar(50);
v_lastname_clean varchar(50);
v_middlename_clean varchar(50);
v_maidenname_clean varchar(50);
v_alias_clean varchar(50);
soundex_firstname varchar(50);
soundex_lastname varchar(50);
soundex_middlename varchar(50);
searchargperson int;
searchargcount int;
argcount int;
personid_list uuid[];
v_dob_from  date;
v_dob_to 	date;
v_soundexsearch boolean;
v_fuzzysearch boolean;

BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
v_liPageNumber  :=  searchObj  ->>  'pagenumber'  ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
v_liPageSize  :=  searchObj  ->>  'pagesize'  ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
v_lvFirstName  :=  searchObj  ->>  'firstname';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
v_lvLastName  :=  searchObj  ->>  'lastname';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
v_lvMiddleName  :=  searchObj  ->>  'middlename';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
v_liAge  :=  searchObj  ->>  'age';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
v_lvRace  :=  searchObj  ->>  'race';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
v_lvGender  :=  searchObj  ->>  'gender';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
v_lvCity  :=  searchObj  ->>  'city';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
v_lvAddress  :=  searchObj  ->>  'address1'; 
v_lvAddress2  :=  searchObj  ->>  'address2'; 
v_lvZip  :=  searchObj  ->>  'zip';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
v_lvState  :=  searchObj  ->>  'state';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
v_lvCounty  :=  searchObj  ->>  'county';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
v_lvPhone  :=  searchObj  ->>  'phone';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
v_ldDOB  :=  searchObj  ->>  'dob';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
v_liDangerous  :=  searchObj  ->>  'dangerous';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
v_liRegion  :=  searchObj  ->>  'region';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
v_dob_from  :=  searchObj  ->>  'es_dob_from';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
v_dob_to  :=  searchObj  ->>  'es_dob_to';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
v_lvMaidenName  :=  searchObj  ->>  'maidenname';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
v_lvSocialMediaSrc  :=  searchObj  ->>  'mediasrc';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
v_lvStateId  :=  searchObj  ->>  'stateid';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
v_lvOccupation  :=  searchObj  ->>  'occupation';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
v_lvFein  :=  searchObj  ->>  'fein';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
v_lvComplaintnumber  :=  searchObj  ->>  'complaintnumber';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
v_lvCjisnumber_spaced  :=  searchObj  ->>  'cjisnumber';
v_lvcjamspid := searchObj  ->>  'cjamspid';
v_lvPetitionid  :=  searchObj  ->>  'petitionid';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
v_lvAlias  :=  searchObj  ->>  'alias';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
v_lvEmail  :=  searchObj  ->>  'email';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
v_pagenumber  :=  v_liPageNumber-1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
v_pageoffset  =  (v_pagenumber  *  v_liPageSize)  ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
v_lvAddress  :=  replace(v_lvAddress,  '  ',  '%');    
v_lvAddress2  :=  replace(v_lvAddress2,  '  ',  '%');
v_lvCjisnumber  := trim(v_lvCjisnumber_spaced);
v_firstname_clean  := trim(lower(v_lvFirstName));
v_lastname_clean   := trim(lower(v_lvLastName));
v_middlename_clean := trim(lower(v_lvMiddleName));
v_maidenname_clean := trim(lower(v_lvMaidenName));
v_alias_clean      := trim(lower(v_lvAlias));
soundex_firstname := soundex(v_firstname_clean);
soundex_lastname := soundex(v_lastname_clean);
soundex_middlename := soundex(v_middlename_clean);
v_lmdmValue :=  searchObj ->> 'mdmId';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
v_lSSNValue :=  searchObj ->> 'ssn';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
v_lDCNValue :=  searchObj ->> 'dcn';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
v_lDLValue  :=  searchObj ->> 'dl';
v_soundexsearch :=  searchObj ->> 'soundexsearch';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
v_fuzzysearch :=  searchObj ->> 'fuzzysearch';         

select count(*) into searchargcount from jsonb_object_keys(searchObj::jsonb) as key
where key in ('age','race','gender','city','address1','address2','zip','state','stateid','county','phone','dob','roletype','interfacetype','personflag',
'dangerous','region','es_dob_from','es_dob_to','dcn','dl','ssn','maidenname','mediasrc','dateofdeath','occupation','fein','complaintnumber','cjisnumber',
'cjamspid','petitionid','alias','email','assistpid','mdmId','firstname','lastname','middlename','activeflag');

select count(*) into searchargperson from jsonb_object_keys(searchObj::jsonb) as key
where key in ('firstname','lastname','middlename');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
IF  (LENGTH(v_lvState)  >  2)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
    SELECT ST.StateAbbr INTO v_lvState                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
    FROM State ST                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
    WHERE ST.StateName = v_lvState;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
END  IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
argcount := 1;
IF (v_lSSNValue IS NOT NULL) THEN
    argcount := argcount + 1;	
END IF;
  
IF (v_lvCjisnumber IS NOT NULL) THEN
    argcount := argcount + 1;
END IF;

IF (v_soundexsearch) then 
        
    RETURN QUERY SELECT count(1)over(),
	(case when searchargperson > 0 and FR.MatchScore <> searchargperson then false else true end) as exactmatch,
    FR.Rankno, 
    'Local'::character  varying,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
    FR.PersonId,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
    case when FR.NameRank >= FR.AliasRank or v_fuzzysearch THEN p.FirstName else 
    (Select al.firstname FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
        WHERE  al.personid  =  FR.personid
        and al.activeflag=1 
        and CASE WHEN v_lvFirstName is NOT NULL THEN soundex_firstname = soundex(trim(lower(al.FirstName)))
        ELSE TRUE END
    limit 1) end,
    case when FR.NameRank >= FR.AliasRank or v_fuzzysearch THEN p.MiddleName else 
    (Select al.middlename FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
        WHERE  al.personid  =  FR.personid
        and al.activeflag=1 
        and CASE WHEN v_lvMiddleName is NOT NULL THEN soundex_middlename = soundex(trim(lower(al.MiddleName)))
        ELSE TRUE END
    limit 1) end,
    case when FR.NameRank >= FR.AliasRank or v_fuzzysearch THEN p.LastName else 
    (Select al.lastname FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
        WHERE  al.personid  =  FR.personid
        and al.activeflag=1 
        and CASE WHEN v_lvLastName is NOT NULL THEN soundex_lastname = soundex(trim(lower(al.LastName)))
        ELSE TRUE END
    limit 1) end,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
    p.DOB,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
    p.DangerLevel,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
    p.dateofdeath,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
    p.isapproxdod,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
    p.suffix,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
    p.prefx,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
    p.deceased,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
    p.socialmediasource,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
    p.userphoto,
    (SELECT  i.PersonIdentifierValue FROM PersonIdentifier AS i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
        WHERE i.PersonId = FR.PersonId AND i.ActiveFlag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
        AND i.PersonIdentifierTypeKey = 'SSN' limit 1)  AS  SSN,
    (SELECT  i.PersonIdentifierValue FROM  PersonIdentifier AS i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
        WHERE i.PersonId = FR.PersonId AND i.ActiveFlag = 1 
        AND i.PersonIdentifierTypeKey =  'MDM_ID' limit 1)  AS mdm_id,
    (SELECT  j.PersonIdentifierValue FROM PersonIdentifier AS j                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
        WHERE j.PersonId = FR.PersonId AND j.ActiveFlag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
        AND j.PersonIdentifierTypeKey = 'DCN' limit 1) AS DCN,
    (SELECT  j.PersonIdentifierValue FROM PersonIdentifier AS j                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
        WHERE j.PersonId = FR.PersonId AND j.ActiveFlag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
        AND j.PersonIdentifierTypeKey = 'DL' limit 1) AS DL,     
    CAST(substring(COALESCE(TRIM(person_address.address),''),1,20)||'~'||  substring(COALESCE(TRIM(person_address.address2),''),1,20)  ||'~'||  COALESCE(TRIM(person_address.city),'')  ||'~'||  COALESCE(TRIM(person_address.zipcode),'')||'~'||  COALESCE(TRIM(person_address.county),'')  ||'~'||  COALESCE(person_address.state,'')as  character  varying) as primaryaddress,
    person_address.address,
    person_address.address2,
    person_address.county,
    person_address.city,
    person_address.state,
    person_address.zipcode,
    (SELECT  PP.phoneNumber FROM PersonPhoneNumber AS PP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
    WHERE PP.PersonId = FR.PersonId AND PP.PersonPhoneTypeKey = 'H' limit 1) AS HomePhone,
    p.GenderTypeKey,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
    (Select al.firstname || ' ' || ( case when al.lastname is not null then al.lastname else '' end ) 
        FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
        WHERE al.personid = FR.personid and al.activeflag=1 and 
        CASE WHEN v_lvAlias is NOT NULL THEN (trim(lower(al.firstname)) ilike left(lower(v_lvAlias),  3) || '%' or trim(lower(al.lastname)) ilike left(lower(v_lvAlias), 12) || '%') ELSE TRUE END limit 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
    ) AS  Alias,
    p.fk_id as assistpid,
    p.cjamspid::varchar,
    p.safehavenbabyflag,
    p.ethnicgrouptypekey,
    coalesce((select pii.personidentifiervalue from personidentifier pii where pii.personidentifiertypekey = 'IRN' and pii.personid = p.personid and pii.activeflag = 1 limit 1), p.cisclientid) as assistpid,
    p.isbioadoptedflag from 
    (SELECT 
        distinct
        p.PersonId,
        CASE WHEN (v_lSSNValue is NOT NULL and i.PersonIdentifierValue = v_lSSNValue) or 
        (v_lvCjisnumber is NOT NULL and (i.PersonIdentifierValue = v_lvCjisnumber or (trim(p.cisclientid) = v_lvCjisnumber::character varying))) 
        THEN 99 ELSE 0 END as RankNo,
        CASE 	WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = trim(lower(p.FirstName)) THEN 1 
                WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = trim(lower(al.FirstName)) THEN 1 
                WHEN v_lvFirstName is not null and trim(lower(p.FirstName)) like v_firstname_clean||'%' THEN 1 
                WHEN v_lvFirstName is not null and trim(lower(al.FirstName)) like v_firstname_clean||'%' THEN 1 
                WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = split_part(trim(lower(p.FirstName)), ' ',1) THEN 1 
                WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = split_part(trim(lower(al.FirstName)), ' ',1) THEN 1 
                ELSE 0 end
        + CASE 	WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = trim(lower(p.LastName)) THEN 1 
                WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = trim(lower(al.LastName)) THEN 1 
                WHEN v_lvLastName is not null and trim(lower(p.LastName)) like v_lastname_clean||'%' THEN 1
                WHEN v_lvLastName is not null and trim(lower(al.LastName)) like v_lastname_clean||'%' THEN 1
                WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = split_part(trim(lower(p.LastName)), ' ',1) THEN 1 
                WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = split_part(trim(lower(al.LastName)), ' ',1) THEN 1 
                ELSE 0 end
        + CASE WHEN v_lvMiddleName is not null and coalesce(v_middlename_clean,' ') = trim(lower(p.MiddleName)) THEN 1 
        WHEN v_lvMiddleName is not null and coalesce(v_middlename_clean,' ') = split_part(trim(lower(p.MiddleName)), ' ',2) THEN 1 ELSE 0 end
        ::int as MatchScore,
        CASE 	WHEN v_lvFirstName is not null THEN COALESCE(difference(v_firstname_clean, trim(lower(p.FirstName))),0) ELSE 0 end
        + CASE 	WHEN v_lvLastName is not null THEN COALESCE(difference(v_lastname_clean, trim(lower(p.LastName))),0) ELSE 0 end
        + CASE 	WHEN v_lvMiddleName is not null THEN COALESCE(difference(v_middlename_clean, trim(lower(p.MiddleName))),0) ELSE 0 end
        ::int as NameRank,
        CASE 	WHEN v_lvFirstName is not null THEN COALESCE(difference(v_firstname_clean, trim(lower(al.FirstName))),0) ELSE 0 end
        + CASE 	WHEN v_lvLastName is not null THEN COALESCE(difference(v_lastname_clean, trim(lower(al.LastName))),0) ELSE 0 end
        + CASE 	WHEN v_lvMiddleName is not null THEN COALESCE(difference(v_middlename_clean, trim(lower(al.MiddleName))),0) ELSE 0 end
        ::int as AliasRank,
        (SELECT PRA.PersonAddressId FROM PersonAddress PRA 
        WHERE PRA.PersonId = p.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
        AND  CASE  WHEN  v_lvAddress  is  NOT  NULL  THEN  (PRA.address  ILIKE  LEFT(v_lvAddress,  5)  ||  '%')  ELSE  TRUE  end
        AND  CASE  WHEN  v_lvAddress2  is  NOT  NULL  THEN  (PRA.address2  ILIKE  LEFT(v_lvAddress2,  5)  ||  '%')  ELSE  TRUE  END
        AND  CASE  WHEN  v_lvZip  is  NOT  NULL  THEN  (PRA.zipcode  ILIKE  LEFT(v_lvZip,  4)  ||  '%')  ELSE  TRUE  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
        AND  CASE  WHEN  v_lvState  is  NOT  NULL  THEN  (PRA.state  ILIKE  v_lvState  ||  '%')  ELSE  TRUE  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
        AND  CASE  WHEN  v_lvCounty  is  NOT  NULL  THEN  (PRA.county  ILIKE  LEFT(v_lvCounty,  3)    ||  '%')  ELSE  TRUE  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
        AND  PRA.ActiveFlag = 1 ORDER BY PRA.insertedon DESC LIMIT 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
        )
    FROM    Person  AS  p  
    LEFT  JOIN  PersonIdentifier  AS  i  ON  i.PersonId  =  p.PersonId 
    LEFT  JOIN  PersonAddress    AS  a  ON  a.PersonId  =  p.PersonId  and  a.ActiveFlag  =  1 
    LEFT  JOIN  PersonPhoneNumber  AS  pn  ON  pn.PersonId  =  p.PersonId
    LEFT  JOIN  PersonEmail  AS  pe  ON  pe.PersonId  =  p.PersonId
    LEFT  JOIN  County        AS  c  ON    a.county :: character varying  =  c.countyid :: character varying
    Left  Join  Alias  As  al  On  al.personid  =  p.personid
    WHERE (p.clientflag is null or p.clientflag = 1 or p.cisclientid is not null)
    AND ((CASE WHEN v_lSSNValue is NOT NULL THEN i.PersonIdentifierValue = v_lSSNValue ELSE False END) OR
    (CASE WHEN v_lvCjisnumber is NOT NULL THEN (i.PersonIdentifierValue = v_lvCjisnumber or (trim(p.cisclientid) = v_lvCjisnumber::character varying)) ELSE False END) OR
    (case when searchargcount > argcount then 
    CASE WHEN v_lvFirstName is NOT NULL THEN (soundex_firstname = soundex(lower(trim(p.FirstName))) or soundex_firstname = soundex(lower(trim(al.FirstName)))) ELSE TRUE END
    AND CASE WHEN v_lvLastName is NOT NULL THEN (soundex_lastname = soundex(lower(trim(p.LastName))) or soundex_lastname = soundex(lower(trim(al.LastName)))) ELSE TRUE END
    AND CASE WHEN v_lvMiddleName is NOT NULL THEN (soundex_middlename = soundex(lower(trim(p.MiddleName))) or soundex_middlename = soundex(lower(trim(al.MiddleName)))) ELSE TRUE END
    AND CASE WHEN v_lvRace is NOT NULL THEN (p.RaceTypeKey = v_lvRace) ELSE TRUE END
    AND CASE WHEN v_lvGender is NOT NULL THEN (p.GenderTypeKey = v_lvGender) ELSE TRUE END
    AND CASE WHEN v_liDangerous is NOT NULL THEN (p.DangerLevel = v_liDangerous) ELSE TRUE END
    AND CASE WHEN v_liRegion is NOT NULL THEN (c.APSRegion = v_liRegion) ELSE TRUE END
    AND CASE WHEN v_lDLValue is NOT NULL THEN (i.PersonIdentifierTypeKey = 'DL' AND i.PersonIdentifierValue ILIKE v_lDLValue) ELSE TRUE END
    and CASE WHEN v_lvStateId is NOT NULL THEN a.state ILIKE v_lvStateId ELSE TRUE end
    AND CASE WHEN v_lvAddress  is  NOT  NULL  THEN  (lower(a.address)  ILIKE  lower(v_lvAddress)||'%' )  ELSE  TRUE  end
    AND CASE WHEN v_lvAddress2  is  NOT  NULL  THEN  (lower(a.address2) ILIKE  lower(v_lvAddress2)||'%' )  ELSE  TRUE  END
    AND CASE WHEN v_lvSocialMediaSrc is NOT NULL THEN (lower(p.socialmediasource) = lower(v_lvSocialMediaSrc)) ELSE TRUE END
    AND CASE WHEN v_lvFein is NOT NULL THEN (p.fein = v_lvFein) ELSE TRUE END
    AND CASE WHEN v_lvComplaintnumber is NOT NULL THEN (p.complaintnumber = v_lvComplaintnumber) ELSE TRUE end
    AND CASE WHEN v_lvcjamspid is NOT NULL THEN ( p.cjamspid = v_lvcjamspid::bigint) ELSE TRUE END
    AND CASE WHEN v_lvPetitionid is NOT NULL THEN (p.petitionid = v_lvPetitionid) ELSE TRUE END
    AND CASE WHEN v_lvAlias is NOT NULL 
        THEN ((concat(trim(lower(al.firstname)), case when al.lastname is not null then '' else ' '|| trim(lower(al.lastname)) end ) = v_alias_clean) and al.akatypetypekey='AN' and al.activeflag=1)
        ELSE true END
    AND CASE WHEN v_lvMaidenName is NOT NULL 
        THEN ((concat(lower(al.firstname), case when al.lastname is not null then '' else ' '|| lower(al.lastname) end ) = v_maidenname_clean) and al.akatypetypekey='MN' and al.activeflag=1)
        ELSE true END
    AND CASE WHEN v_lvZip is NOT NULL THEN (lower(a.zipcode) = lower(v_lvZip)) ELSE TRUE END
    AND CASE WHEN v_lvState is NOT NULL THEN (a.state ILIKE v_lvState) ELSE TRUE END
    AND CASE WHEN v_lvCounty is NOT NULL THEN (a.county ILIKE v_lvCounty) ELSE TRUE END
    AND CASE WHEN v_lvCity is NOT NULL THEN (lower(a.city) = lower(v_lvCity)) ELSE TRUE END
    AND CASE WHEN v_lDCNValue is NOT NULL THEN (i.PersonIdentifierTypeKey = 'DCN' and i.PersonIdentifierValue ILIKE v_lDCNValue) ELSE TRUE END
    AND CASE WHEN v_lvPhone is NOT NULL THEN (pn.phoneNumber ILIKE v_lvPhone) ELSE TRUE END
    AND CASE WHEN v_lvEmail is NOT NULL THEN (pe.email ILIKE v_lvEmail) ELSE TRUE END
    AND CASE WHEN v_lvOccupation is NOT NULL THEN (p.occupation ILIKE v_lvOccupation) ELSE TRUE END
    AND CASE WHEN v_liAge is NOT NULL then date_part('year', age(now(), p.DOB)) = v_liAge ELSE TRUE END
    AND CASE WHEN v_lmdmValue is NOT NULL THEN (i.PersonIdentifierTypeKey = 'MDM_ID' and i.PersonIdentifierValue ilike '%'  || v_lmdmValue ||  '%' ) ELSE TRUE END
    AND CASE WHEN v_ldDOB is NOT NULL THEN (p.DOB BETWEEN v_dob_from AND v_dob_to) ELSE TRUE END else false end))
    AND p.ActiveFlag  =  1
    LIMIT v_liPageSize OFFSET v_pageoffset) as FR
    JOIN  Person AS p ON p.PersonId = FR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
    left join lateral 
    (SELECT PA.address, PA.address2, PA.city, PA.state, PA.zipcode,
    (select CC.countyname from  County cc where  cc.countyid :: character varying = PA.county :: character varying )  as county 
    FROM  PersonAddress  AS  PA           
    WHERE PA.PersonId  =  FR.PersonId AND  PA.PersonAddressId = FR.PersonAddressId limit 1) person_address on true
     ;	

Elseif (v_fuzzysearch) then 

    RETURN QUERY SELECT count(1)over(),
	(case when searchargperson > 0 and FR.MatchScore <> searchargperson then false else true end) as exactmatch,
    FR.Rankno, 
    'Local'::character  varying,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
    FR.PersonId,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
    case when FR.NameRank <= FR.AliasRank THEN p.FirstName else 
    (Select al.firstname FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
        WHERE  al.personid  =  FR.personid
        and al.activeflag=1 
        and CASE WHEN v_lvFirstName is NOT NULL THEN levenshtein(lower(trim(al.FirstName)),v_firstname_clean,1,1,1) < 4
        ELSE TRUE END
    limit 1) end,
    case when FR.NameRank <= FR.AliasRank THEN p.MiddleName else 
    (Select al.middlename FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
        WHERE  al.personid  =  FR.personid
        and al.activeflag=1 
        and CASE WHEN v_lvMiddleName is NOT NULL THEN levenshtein(lower(trim(al.MiddleName)),v_middlename_clean,1,1,1) < 4
        ELSE TRUE END
    limit 1) end,
    case when FR.NameRank <= FR.AliasRank THEN p.LastName else 
    (Select al.lastname FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
        WHERE  al.personid  =  FR.personid
        and al.activeflag=1 
        and CASE WHEN v_lvLastName is NOT NULL THEN levenshtein(lower(trim(al.LastName)),v_lastname_clean,1,1,1) < 4
        ELSE TRUE END
    limit 1) end,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
    p.DOB,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
    p.DangerLevel,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
    p.dateofdeath,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
    p.isapproxdod,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
    p.suffix,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
    p.prefx,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
    p.deceased,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
    p.socialmediasource,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
    p.userphoto,
    (SELECT  i.PersonIdentifierValue FROM PersonIdentifier AS i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
        WHERE i.PersonId = FR.PersonId AND i.ActiveFlag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
        AND i.PersonIdentifierTypeKey = 'SSN' limit 1)  AS  SSN,
    (SELECT  i.PersonIdentifierValue FROM  PersonIdentifier AS i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
        WHERE i.PersonId = FR.PersonId AND i.ActiveFlag = 1 
        AND i.PersonIdentifierTypeKey =  'MDM_ID' limit 1)  AS mdm_id,
    (SELECT  j.PersonIdentifierValue FROM PersonIdentifier AS j                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
        WHERE j.PersonId = FR.PersonId AND j.ActiveFlag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
        AND j.PersonIdentifierTypeKey = 'DCN' limit 1) AS DCN,
    (SELECT  j.PersonIdentifierValue FROM PersonIdentifier AS j                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
        WHERE j.PersonId = FR.PersonId AND j.ActiveFlag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
        AND j.PersonIdentifierTypeKey = 'DL' limit 1) AS DL,     
    CAST(substring(COALESCE(TRIM(person_address.address),''),1,20)||'~'||  substring(COALESCE(TRIM(person_address.address2),''),1,20)  ||'~'||  COALESCE(TRIM(person_address.city),'')  ||'~'||  COALESCE(TRIM(person_address.zipcode),'')||'~'||  COALESCE(TRIM(person_address.county),'')  ||'~'||  COALESCE(person_address.state,'')as  character  varying) as primaryaddress,
    person_address.address,
    person_address.address2,
    person_address.county,
    person_address.city,
    person_address.state,
    person_address.zipcode,
    (SELECT  PP.phoneNumber FROM PersonPhoneNumber AS PP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
    WHERE PP.PersonId = FR.PersonId AND PP.PersonPhoneTypeKey = 'H' limit 1) AS HomePhone,
    p.GenderTypeKey,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
    (Select al.firstname || ' ' || ( case when al.lastname is not null then al.lastname else '' end ) 
        FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
        WHERE al.personid = FR.personid and al.activeflag=1 and 
        CASE WHEN v_lvAlias is NOT NULL THEN (trim(lower(al.firstname)) ilike left(lower(v_lvAlias),  3) || '%' or trim(lower(al.lastname)) ilike left(lower(v_lvAlias), 12) || '%') ELSE TRUE END limit 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
    ) AS  Alias,
    p.fk_id as assistpid,
    p.cjamspid::varchar,
    p.safehavenbabyflag,
    p.ethnicgrouptypekey,
    coalesce((select pii.personidentifiervalue from personidentifier pii where pii.personidentifiertypekey = 'IRN' and pii.personid = p.personid and pii.activeflag = 1 limit 1), p.cisclientid) as assistpid,
    p.isbioadoptedflag from 
    (SELECT 
        distinct
        p.PersonId,
        CASE WHEN (v_lSSNValue is NOT NULL and i.PersonIdentifierValue = v_lSSNValue) or 
        (v_lvCjisnumber is NOT NULL and (i.PersonIdentifierValue = v_lvCjisnumber or (trim(p.cisclientid) = v_lvCjisnumber::character varying))) 
        THEN 99 ELSE 0 END as RankNo,
        CASE 	WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = trim(lower(p.FirstName)) THEN 1 
                WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = trim(lower(al.FirstName)) THEN 1 
                WHEN v_lvFirstName is not null and trim(lower(p.FirstName)) like v_firstname_clean||'%' THEN 1 
                WHEN v_lvFirstName is not null and trim(lower(al.FirstName)) like v_firstname_clean||'%' THEN 1 
                WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = split_part(trim(lower(p.FirstName)), ' ',1) THEN 1 
                WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = split_part(trim(lower(al.FirstName)), ' ',1) THEN 1 
                ELSE 0 end
        + CASE 	WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = trim(lower(p.LastName)) THEN 1 
                WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = trim(lower(al.LastName)) THEN 1 
                WHEN v_lvLastName is not null and trim(lower(p.LastName)) like v_lastname_clean||'%' THEN 1
                WHEN v_lvLastName is not null and trim(lower(al.LastName)) like v_lastname_clean||'%' THEN 1
                WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = split_part(trim(lower(p.LastName)), ' ',1) THEN 1 
                WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = split_part(trim(lower(al.LastName)), ' ',1) THEN 1 
                ELSE 0 end
        + CASE WHEN v_lvMiddleName is not null and coalesce(v_middlename_clean,' ') = trim(lower(p.MiddleName)) THEN 1 
        WHEN v_lvMiddleName is not null and coalesce(v_middlename_clean,' ') = split_part(trim(lower(p.MiddleName)), ' ',2) THEN 1 ELSE 0 end
        ::int as MatchScore,
        CASE WHEN v_lvFirstName is not null THEN coalesce(levenshtein(lower(trim(p.FirstName)),v_firstname_clean,1,1,1),4) else 0 end 
        + CASE 	WHEN v_lvLastName is not null THEN coalesce(levenshtein(lower(trim(p.LastName)),v_lastname_clean,1,1,1),4) else 0 end  
        + CASE 	WHEN v_lvMiddleName is not null then coalesce(levenshtein(lower(trim(p.MiddleName)),v_middlename_clean,1,1,1),4) ELSE 0 end as NameRank,
        CASE WHEN v_lvFirstName is not null THEN coalesce(levenshtein(lower(trim(al.FirstName)),v_firstname_clean,1,1,1),4) ELSE 0 end
        + CASE 	WHEN v_lvLastName is not null THEN coalesce(levenshtein(lower(trim(al.LastName)),v_lastname_clean,1,1,1),4) ELSE 0 end
        + CASE 	WHEN v_lvMiddleName is not null THEN coalesce(levenshtein(lower(trim(al.MiddleName)),v_middlename_clean,1,1,1),4) ELSE 0 end
        ::int as AliasRank,
        (SELECT PRA.PersonAddressId FROM PersonAddress PRA 
        WHERE PRA.PersonId = p.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
        AND  CASE  WHEN  v_lvAddress  is  NOT  NULL  THEN  (PRA.address  ILIKE  LEFT(v_lvAddress,  5)  ||  '%')  ELSE  TRUE  end
        AND  CASE  WHEN  v_lvAddress2  is  NOT  NULL  THEN  (PRA.address2  ILIKE  LEFT(v_lvAddress2,  5)  ||  '%')  ELSE  TRUE  END
        AND  CASE  WHEN  v_lvZip  is  NOT  NULL  THEN  (PRA.zipcode  ILIKE  LEFT(v_lvZip,  4)  ||  '%')  ELSE  TRUE  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
        AND  CASE  WHEN  v_lvState  is  NOT  NULL  THEN  (PRA.state  ILIKE  v_lvState  ||  '%')  ELSE  TRUE  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
        AND  CASE  WHEN  v_lvCounty  is  NOT  NULL  THEN  (PRA.county  ILIKE  LEFT(v_lvCounty,  3)    ||  '%')  ELSE  TRUE  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
        AND  PRA.ActiveFlag = 1 ORDER BY PRA.insertedon DESC LIMIT 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
        )
    FROM  Person  AS  p  
    LEFT  JOIN  PersonIdentifier  AS i ON  i.PersonId  =  p.PersonId 
    LEFT  JOIN  PersonAddress    AS a ON  a.PersonId  =  p.PersonId  and  a.ActiveFlag  =  1 
    LEFT  JOIN  PersonPhoneNumber  AS pn ON pn.PersonId  =  p.PersonId
    LEFT  JOIN  PersonEmail  AS pe ON pe.PersonId = p.PersonId
    LEFT  JOIN  County  AS  c  ON a.county :: character varying  =  c.countyid :: character varying
    Left  Join  Alias  As  al  On al.personid  =  p.personid
    WHERE (p.clientflag is null or p.clientflag = 1 or p.cisclientid is not null)
    AND ((CASE WHEN v_lSSNValue is NOT NULL THEN i.PersonIdentifierValue = v_lSSNValue ELSE False END) OR
    (CASE WHEN v_lvCjisnumber is NOT NULL THEN (i.PersonIdentifierValue = v_lvCjisnumber or (trim(p.cisclientid) = v_lvCjisnumber::character varying)) ELSE False END) OR
    (case when searchargcount > argcount then 
    CASE WHEN v_lvFirstName is NOT NULL THEN (levenshtein(lower(trim(p.FirstName)),v_firstname_clean,1,1,1) < 4) or (levenshtein(lower(trim(al.FirstName)),v_firstname_clean,1,1,1) < 4) ELSE TRUE END
    AND CASE WHEN v_lvLastName is NOT NULL THEN (levenshtein(lower(trim(p.LastName)),v_lastname_clean,1,1,1) < 4) or (levenshtein(lower(trim(al.LastName)),v_lastname_clean,1,1,1) < 4)  ELSE TRUE END
    AND CASE WHEN v_lvMiddleName is NOT NULL THEN (levenshtein(lower(trim(p.MiddleName)),v_middlename_clean,1,1,1) < 4) or (levenshtein(lower(trim(al.MiddleName)),v_middlename_clean,1,1,1) < 4)  ELSE TRUE END
    AND CASE WHEN v_lvRace is NOT NULL THEN (p.RaceTypeKey = v_lvRace) ELSE TRUE END
    AND CASE WHEN v_lvGender is NOT NULL THEN (p.GenderTypeKey = v_lvGender) ELSE TRUE END
    AND CASE WHEN v_liDangerous is NOT NULL THEN (p.DangerLevel = v_liDangerous) ELSE TRUE END
    AND CASE WHEN v_liRegion is NOT NULL THEN (c.APSRegion = v_liRegion) ELSE TRUE END
    AND CASE WHEN v_lDLValue is NOT NULL THEN (i.PersonIdentifierTypeKey = 'DL' AND i.PersonIdentifierValue ILIKE v_lDLValue) ELSE TRUE END
    and CASE WHEN v_lvStateId is NOT NULL THEN a.state ILIKE v_lvStateId ELSE TRUE end
    AND CASE WHEN v_lvAddress  is  NOT  NULL  THEN  (lower(a.address)  ILIKE  lower(v_lvAddress)||'%' )  ELSE  TRUE  end
    AND CASE WHEN v_lvAddress2  is  NOT  NULL  THEN  (lower(a.address2) ILIKE  lower(v_lvAddress2)||'%' )  ELSE  TRUE  END
    AND CASE WHEN v_lvSocialMediaSrc is NOT NULL THEN (lower(p.socialmediasource) = lower(v_lvSocialMediaSrc)) ELSE TRUE END
    AND CASE WHEN v_lvFein is NOT NULL THEN (p.fein = v_lvFein) ELSE TRUE END
    AND CASE WHEN v_lvComplaintnumber is NOT NULL THEN (p.complaintnumber = v_lvComplaintnumber) ELSE TRUE end
    AND CASE WHEN v_lvcjamspid is NOT NULL THEN ( p.cjamspid = v_lvcjamspid::bigint) ELSE TRUE END
    AND CASE WHEN v_lvPetitionid is NOT NULL THEN (p.petitionid = v_lvPetitionid) ELSE TRUE END
    AND CASE WHEN v_lvAlias is NOT NULL 
        THEN ((concat(trim(lower(al.firstname)), case when al.lastname is not null then '' else ' '|| trim(lower(al.lastname)) end ) = v_alias_clean) and al.akatypetypekey='AN' and al.activeflag=1)
        ELSE true END
    AND CASE WHEN v_lvMaidenName is NOT NULL 
        THEN ((concat(lower(al.firstname), case when al.lastname is not null then '' else ' '|| lower(al.lastname) end ) = v_maidenname_clean) and al.akatypetypekey='MN' and al.activeflag=1)
        ELSE true END
    AND CASE WHEN v_lvZip is NOT NULL THEN (lower(a.zipcode) = lower(v_lvZip)) ELSE TRUE END
    AND CASE WHEN v_lvState is NOT NULL THEN (a.state ILIKE v_lvState) ELSE TRUE END
    AND CASE WHEN v_lvCounty is NOT NULL THEN (a.county ILIKE v_lvCounty) ELSE TRUE END
    AND CASE WHEN v_lvCity is NOT NULL THEN (lower(a.city) = lower(v_lvCity)) ELSE TRUE END
    AND CASE WHEN v_lDCNValue is NOT NULL THEN (i.PersonIdentifierTypeKey = 'DCN' and i.PersonIdentifierValue ILIKE v_lDCNValue) ELSE TRUE END
    AND CASE WHEN v_lvPhone is NOT NULL THEN (pn.phoneNumber ILIKE v_lvPhone) ELSE TRUE END
    AND CASE WHEN v_lvEmail is NOT NULL THEN (pe.email ILIKE v_lvEmail) ELSE TRUE END
    AND CASE WHEN v_lvOccupation is NOT NULL THEN (p.occupation ILIKE v_lvOccupation) ELSE TRUE END
    AND CASE WHEN v_liAge is NOT NULL then date_part('year', age(now(), p.DOB)) = v_liAge ELSE TRUE END
    AND CASE WHEN v_lmdmValue is NOT NULL THEN (i.PersonIdentifierTypeKey = 'MDM_ID' and i.PersonIdentifierValue ilike '%'  || v_lmdmValue ||  '%' ) ELSE TRUE END
    AND CASE WHEN v_ldDOB is NOT NULL THEN (p.DOB BETWEEN v_dob_from AND v_dob_to) ELSE TRUE END else false end))
    AND p.ActiveFlag  =  1
    ) as FR 
    JOIN  Person AS p ON p.PersonId = FR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
    left join lateral 
    (SELECT PA.address, PA.address2, PA.city, PA.state, PA.zipcode,
    (select CC.countyname from  County cc where  cc.countyid :: character varying = PA.county :: character varying )  as county 
    FROM  PersonAddress  AS  PA           
    WHERE PA.PersonId  =  FR.PersonId AND  PA.PersonAddressId = FR.PersonAddressId limit 1) person_address on true
    order by RankNo desc, (case when FR.NameRank <= FR.AliasRank then FR.NameRank else FR.AliasRank end) asc
    LIMIT v_liPageSize OFFSET v_pageoffset;	

Else

    RETURN QUERY SELECT count(1)over(),
	true as exactmatch,
    FR.Rankno, 
    'Local'::character  varying,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
    FR.PersonId,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
    case when FR.NameRank >= FR.AliasRank THEN p.FirstName else 
    (Select al.firstname FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
        WHERE  al.personid  =  FR.personid
        and al.activeflag=1 
        and CASE WHEN v_lvFirstName is NOT NULL THEN v_firstname_clean = trim(lower(al.FirstName))
        ELSE TRUE END
    limit 1) end,
    case when FR.NameRank >= FR.AliasRank THEN p.MiddleName else 
    (Select al.middlename FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
        WHERE  al.personid  =  FR.personid
        and al.activeflag=1 
        and CASE WHEN v_lvMiddleName is NOT NULL THEN v_middlename_clean = trim(lower(al.MiddleName))
        ELSE TRUE END
    limit 1) end,
    case when FR.NameRank >= FR.AliasRank THEN p.LastName else 
    (Select al.lastname FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
        WHERE  al.personid  =  FR.personid
        and al.activeflag=1 
        and CASE WHEN v_lvLastName is NOT NULL THEN v_lastname_clean = trim(lower(al.LastName))
        ELSE TRUE END
    limit 1) end,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
    p.DOB,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
    p.DangerLevel,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
    p.dateofdeath,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
    p.isapproxdod,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
    p.suffix,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
    p.prefx,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
    p.deceased,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
    p.socialmediasource,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
    p.userphoto,
    (SELECT  i.PersonIdentifierValue FROM PersonIdentifier AS i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
        WHERE i.PersonId = FR.PersonId AND i.ActiveFlag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
        AND i.PersonIdentifierTypeKey = 'SSN' limit 1)  AS  SSN,
    (SELECT  i.PersonIdentifierValue FROM  PersonIdentifier AS i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
        WHERE i.PersonId = FR.PersonId AND i.ActiveFlag = 1 
        AND i.PersonIdentifierTypeKey =  'MDM_ID' limit 1)  AS mdm_id,
    (SELECT  j.PersonIdentifierValue FROM PersonIdentifier AS j                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
        WHERE j.PersonId = FR.PersonId AND j.ActiveFlag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
        AND j.PersonIdentifierTypeKey = 'DCN' limit 1) AS DCN,
    (SELECT  j.PersonIdentifierValue FROM PersonIdentifier AS j                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
        WHERE j.PersonId = FR.PersonId AND j.ActiveFlag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
        AND j.PersonIdentifierTypeKey = 'DL' limit 1) AS DL,     
    CAST(substring(COALESCE(TRIM(person_address.address),''),1,20)||'~'||  substring(COALESCE(TRIM(person_address.address2),''),1,20)  ||'~'||  COALESCE(TRIM(person_address.city),'')  ||'~'||  COALESCE(TRIM(person_address.zipcode),'')||'~'||  COALESCE(TRIM(person_address.county),'')  ||'~'||  COALESCE(person_address.state,'')as  character  varying) as primaryaddress,
    person_address.address,
    person_address.address2,
    person_address.county,
    person_address.city,
    person_address.state,
    person_address.zipcode,
    (SELECT  PP.phoneNumber FROM PersonPhoneNumber AS PP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
    WHERE PP.PersonId = FR.PersonId AND PP.PersonPhoneTypeKey = 'H' limit 1) AS HomePhone,
    p.GenderTypeKey,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
    (Select al.firstname || ' ' || ( case when al.lastname is not null then al.lastname else '' end ) 
        FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
        WHERE al.personid = FR.personid and al.activeflag=1 and 
        CASE WHEN v_lvAlias is NOT NULL THEN (trim(lower(al.firstname)) ilike left(lower(v_lvAlias),  3) || '%' or trim(lower(al.lastname)) ilike left(lower(v_lvAlias), 12) || '%') ELSE TRUE END limit 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
    ) AS  Alias,
    p.fk_id as assistpid,
    p.cjamspid::varchar,
    p.safehavenbabyflag,
    p.ethnicgrouptypekey,
    coalesce((select pii.personidentifiervalue from personidentifier pii where pii.personidentifiertypekey = 'IRN' and pii.personid = p.personid and pii.activeflag = 1 limit 1), p.cisclientid) as assistpid,
    p.isbioadoptedflag
    from 
    (SELECT 
        distinct
        p.PersonId,
        CASE WHEN (v_lSSNValue is NOT NULL and i.PersonIdentifierValue = v_lSSNValue) or 
        (v_lvCjisnumber is NOT NULL and (i.PersonIdentifierValue = v_lvCjisnumber or (trim(p.cisclientid) = v_lvCjisnumber::character varying))) 
        THEN 99 ELSE 0 END as RankNo,
        searchargperson as MatchScore,
        CASE WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = trim(lower(p.FirstName)) THEN 1 ELSE 0 end
        + CASE WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = trim(lower(p.LastName)) THEN 1 ELSE 0 end
        + CASE 	WHEN v_lvMiddleName is not null and coalesce(v_middlename_clean,' ') = trim(lower(p.MiddleName)) THEN 1 ELSE 0 end
        ::int as NameRank,
        CASE 	WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = trim(lower(al.FirstName)) THEN 1 ELSE 0 end
        + CASE 	WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = trim(lower(al.LastName)) THEN 1 ELSE 0 end
        + CASE 	WHEN v_lvMiddleName is not null and coalesce(v_middlename_clean,' ') = trim(lower(al.MiddleName)) THEN 1 ELSE 0 end
        ::int as AliasRank,
        (SELECT PRA.PersonAddressId FROM PersonAddress PRA 
        WHERE PRA.PersonId = p.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
        AND  CASE  WHEN  v_lvAddress  is  NOT  NULL  THEN  (PRA.address  ILIKE  LEFT(v_lvAddress,  5)  ||  '%')  ELSE  TRUE  end
        AND  CASE  WHEN  v_lvAddress2  is  NOT  NULL  THEN  (PRA.address2  ILIKE  LEFT(v_lvAddress2,  5)  ||  '%')  ELSE  TRUE  END
        AND  CASE  WHEN  v_lvZip  is  NOT  NULL  THEN  (PRA.zipcode  ILIKE  LEFT(v_lvZip,  4)  ||  '%')  ELSE  TRUE  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
        AND  CASE  WHEN  v_lvState  is  NOT  NULL  THEN  (PRA.state  ILIKE  v_lvState  ||  '%')  ELSE  TRUE  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
        AND  CASE  WHEN  v_lvCounty  is  NOT  NULL  THEN  (PRA.county  ILIKE  LEFT(v_lvCounty,  3)    ||  '%')  ELSE  TRUE  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
        AND  PRA.ActiveFlag = 1 ORDER BY PRA.insertedon DESC LIMIT 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
        )
    FROM    Person  AS  p  
    LEFT  JOIN  PersonIdentifier  AS  i  ON  i.PersonId  =  p.PersonId 
    LEFT  JOIN  PersonAddress    AS  a  ON  a.PersonId  =  p.PersonId  and  a.ActiveFlag  =  1 
    LEFT  JOIN  PersonPhoneNumber  AS  pn  ON  pn.PersonId  =  p.PersonId
    LEFT  JOIN  PersonEmail  AS  pe  ON  pe.PersonId  =  p.PersonId
    LEFT  JOIN  County        AS  c  ON    a.county :: character varying  =  c.countyid :: character varying
    Left  Join  Alias  As  al  On  al.personid  =  p.personid
    WHERE (p.clientflag is null or p.clientflag = 1 or p.cisclientid is not null)
    AND ((CASE WHEN v_lSSNValue is NOT NULL THEN i.PersonIdentifierValue = v_lSSNValue ELSE False END) OR
    (CASE WHEN v_lvCjisnumber is NOT NULL THEN (i.PersonIdentifierValue = v_lvCjisnumber or (trim(p.cisclientid) = v_lvCjisnumber::character varying)) ELSE False END) OR
    (case when searchargcount > argcount then 
    CASE WHEN v_lvFirstName is NOT NULL THEN (v_firstname_clean = lower(trim(p.FirstName)) or v_firstname_clean = lower(trim(al.FirstName))) ELSE TRUE END
    AND CASE WHEN v_lvLastName is NOT NULL THEN (v_lastname_clean = lower(trim(p.LastName)) or v_lastname_clean = lower(trim(al.LastName))) ELSE TRUE END
    AND CASE WHEN v_lvMiddleName is NOT NULL THEN (v_middlename_clean = lower(trim(p.MiddleName)) or v_middlename_clean = lower(trim(al.MiddleName))) ELSE TRUE END
    AND CASE WHEN v_lvRace is NOT NULL THEN (p.RaceTypeKey = v_lvRace) ELSE TRUE END
    AND CASE WHEN v_lvGender is NOT NULL THEN (p.GenderTypeKey = v_lvGender) ELSE TRUE END
    AND CASE WHEN v_liDangerous is NOT NULL THEN (p.DangerLevel = v_liDangerous) ELSE TRUE END
    AND CASE WHEN v_liRegion is NOT NULL THEN (c.APSRegion = v_liRegion) ELSE TRUE END
    AND CASE WHEN v_lDLValue is NOT NULL THEN (i.PersonIdentifierTypeKey = 'DL' AND i.PersonIdentifierValue ILIKE v_lDLValue) ELSE TRUE END
    and CASE WHEN v_lvStateId is NOT NULL THEN a.state ILIKE v_lvStateId ELSE TRUE end
    AND CASE WHEN v_lvAddress  is  NOT  NULL  THEN  (lower(a.address)  ILIKE  lower(v_lvAddress)||'%' )  ELSE  TRUE  end
    AND CASE WHEN v_lvAddress2  is  NOT  NULL  THEN  (lower(a.address2) ILIKE  lower(v_lvAddress2)||'%' )  ELSE  TRUE  END
    AND CASE WHEN v_lvSocialMediaSrc is NOT NULL THEN (lower(p.socialmediasource) = lower(v_lvSocialMediaSrc)) ELSE TRUE END
    AND CASE WHEN v_lvFein is NOT NULL THEN (p.fein = v_lvFein) ELSE TRUE END
    AND CASE WHEN v_lvComplaintnumber is NOT NULL THEN (p.complaintnumber = v_lvComplaintnumber) ELSE TRUE end
    AND CASE WHEN v_lvcjamspid is NOT NULL THEN ( p.cjamspid = v_lvcjamspid::bigint) ELSE TRUE END
    AND CASE WHEN v_lvPetitionid is NOT NULL THEN (p.petitionid = v_lvPetitionid) ELSE TRUE END
    AND CASE WHEN v_lvAlias is NOT NULL 
        THEN ((concat(trim(lower(al.firstname)), case when al.lastname is not null then '' else ' '|| trim(lower(al.lastname)) end ) = v_alias_clean) and al.akatypetypekey='AN' and al.activeflag=1)
        ELSE true END
    AND CASE WHEN v_lvMaidenName is NOT NULL 
        THEN ((concat(lower(al.firstname), case when al.lastname is not null then '' else ' '|| lower(al.lastname) end ) = v_maidenname_clean) and al.akatypetypekey='MN' and al.activeflag=1)
        ELSE true END
    AND CASE WHEN v_lvZip is NOT NULL THEN (lower(a.zipcode) = lower(v_lvZip)) ELSE TRUE END
    AND CASE WHEN v_lvState is NOT NULL THEN (a.state ILIKE v_lvState) ELSE TRUE END
    AND CASE WHEN v_lvCounty is NOT NULL THEN (a.county ILIKE v_lvCounty) ELSE TRUE END
    AND CASE WHEN v_lvCity is NOT NULL THEN (lower(a.city) = lower(v_lvCity)) ELSE TRUE END
    AND CASE WHEN v_lDCNValue is NOT NULL THEN (i.PersonIdentifierTypeKey = 'DCN' and i.PersonIdentifierValue ILIKE v_lDCNValue) ELSE TRUE END
    AND CASE WHEN v_lvPhone is NOT NULL THEN (pn.phoneNumber ILIKE v_lvPhone) ELSE TRUE END
    AND CASE WHEN v_lvEmail is NOT NULL THEN (pe.email ILIKE v_lvEmail) ELSE TRUE END
    AND CASE WHEN v_lvOccupation is NOT NULL THEN (p.occupation ILIKE v_lvOccupation) ELSE TRUE END
    AND CASE WHEN v_liAge is NOT NULL then date_part('year', age(now(), p.DOB)) = v_liAge ELSE TRUE END
    AND CASE WHEN v_lmdmValue is NOT NULL THEN (i.PersonIdentifierTypeKey = 'MDM_ID' and i.PersonIdentifierValue ilike '%'  || v_lmdmValue ||  '%' ) ELSE TRUE END
    AND CASE WHEN v_ldDOB is NOT NULL THEN (p.DOB BETWEEN v_dob_from AND v_dob_to) ELSE TRUE END else false end))
    AND p.ActiveFlag  =  1 
    LIMIT v_liPageSize OFFSET v_pageoffset) as FR 
    JOIN  Person AS p ON p.PersonId = FR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
    left join lateral 
    (SELECT PA.address, PA.address2, PA.city, PA.state, PA.zipcode,
    (select CC.countyname from  County cc where  cc.countyid :: character varying = PA.county :: character varying )  as county 
    FROM  PersonAddress  AS  PA  WHERE PA.PersonId  =  FR.PersonId AND  PA.PersonAddressId = FR.PersonAddressId limit 1) person_address on true;	

End IF ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 END;

 $function$;
 